#include <LiquidCrystal.h>

// Настройка пинов для платы LCD Keypad Shield
LiquidCrystal lcd(8, 9, 4, 5, 6, 7); 

void setup() {
  lcd.begin(16, 2);              // Включаем экран: 16 символов, 2 строки
  lcd.setCursor(0, 0);           // Курсор на первую строку
  lcd.print("Arduino Shield");   // Печатаем текст на первой строке
}

void loop() {
  int x = analogRead(A0);        // Читаем сигнал от кнопок на пине A0
  lcd.setCursor(0, 1);           // Переводим курсор на вторую строку

  // Проверяем, какая кнопка нажата
  if (x < 60) {
    lcd.print("Button: RIGHT ");
  } else if (x < 200) {
    lcd.print("Button: UP    ");
  } else if (x < 400) {
    lcd.print("Button: DOWN  ");
  } else if (x < 600) {
    lcd.print("Button: LEFT  ");
  } else if (x < 800) {
    lcd.print("Button: SELECT");
  } else {
    lcd.print("Press any key "); // Если ни одна кнопка не зажата
  }
}
